// ... (imports remain the same)

export default function MediaStage({ images, videoId }: { images: string[]; videoId: string }) {
  const [index, setIndex] = useState(0);
  const [activeMode, setActiveMode] = useState<"image" | "video">("image");
  const [isZoomed, setIsZoomed] = useState(false);

  const lastTap = useRef<number>(0);
  const ZOOM_LEVEL = 2.6;

  const handleInteraction = (e: React.PointerEvent) => {
    const now = Date.now();
    if (now - lastTap.current < 300) {
      setIsZoomed(!isZoomed);
      lastTap.current = 0;
      return;
    }
    lastTap.current = now;
  };

  const handleDragEnd = (event: any, info: any) => {
    // If zoomed, we only want to swap images if the user swiped HARD 
    // Otherwise, treat it as panning inside the zoomed image.
    if (activeMode === "video") return;

    const swipeThreshold = 50; 
    const lastIndex = images.length - 1;

    // Only trigger slide change if NOT zoomed, OR if zoomed but swiped past a large threshold
    if (!isZoomed) {
      if (info.offset.x < -swipeThreshold) {
        setIndex((prev) => (prev === lastIndex ? 0 : prev + 1));
      } else if (info.offset.x > swipeThreshold) {
        setIndex((prev) => (prev === 0 ? lastIndex : prev - 1));
      }
    }
  };

  return (
    <div className="relative w-full group select-none touch-none">
      <div
        className="relative aspect-3/4 rounded-[2.5rem] overflow-hidden cursor-grab active:cursor-grabbing bg-white"
        onPointerDown={handleInteraction}
      >
        <AnimatePresence mode="wait">
          {activeMode === "image" ? (
            <motion.div
              key={`img-wrap-${index}`}
              className="w-full h-full bg-white overflow-hidden"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
            >
              <motion.div
                className="w-full h-full flex items-center justify-center"
                drag
                // Key Fix: Use a high dragElastic so the user can always feel the 
                // "pull" even at the edges, preventing the "stuck" feeling.
                dragConstraints={{ left: -400, right: 400, top: -500, bottom: 500 }}
                dragElastic={isZoomed ? 0.1 : 0.05} 
                onDragEnd={handleDragEnd}
                // When not zoomed, we snap back to center (0,0)
                animate={{
                  x: isZoomed ? undefined : 0,
                  y: isZoomed ? undefined : 0,
                  scale: isZoomed ? ZOOM_LEVEL : 1,
                }}
                transition={{ type: "spring", stiffness: 300, damping: 30 }}
              >
                <motion.img
                  src={images[index]}
                  alt="Product"
                  className="w-full h-full object-cover pointer-events-none"
                />
              </motion.div>
            </motion.div>
          ) : (
            /* ... Video Code ... */
            <motion.div key="video" className="w-full h-full bg-black">
               <iframe 
                src={`https://www.youtube.com/embed/${videoId}?autoplay=1&mute=1&loop=1&playlist=${videoId}&controls=0`}
                className="w-full h-full scale-[1.35] pointer-events-none" 
               />
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* ... Capsule Switcher Code ... */}
    </div>
  );
}